var i=[{title:`Woche eins: die Routine lernen`,text:`Wähle zwei kurze Ganzkörpereinheiten und mache an anderen Tagen leichte Spaziergänge, wenn dir danach ist. Übe die grundlegenden Muster Kniebeuge, Hüftbeuge, Drücken, Ziehen und Rumpf mit Bewegungen, die zu deiner Ausrüstung und deinem Körper passen. Eine erste Einheit kann aus einem oder zwei Sätzen mehrerer Übungen bestehen.`},{title:`Woche zwei bis vier: wiederholen und beobachten`,text:`Behalte dieselben Übungen und füge dann langsam Wiederholungen, etwas Last oder einen zusätzlichen Satz hinzu, wenn du dich gut erholst. Kleine Steigerungen, die du durchhalten kannst, helfen dir, Selbstvertrauen aufzubauen. Lies nicht jede neue Empfindung oder jeden Muskelkater als Grund, den ganzen Plan zu ändern.`},{title:`Beispiel`,text:`Mache montags und donnerstags kontrollierte Stuhl-Kniebeugen, gestütztes Rudern, Wand-Liegestütze und ein kurzes Core-Halten. Füge an einem anderen Tag einen bequemen Spaziergang hinzu. Wenn eine Bewegung zu schwer ist, wähle eine leichtere Version. Wenn sie sehr leicht ist, mache sie schrittweise schwerer und behalte die Kontrolle.`},{title:`Was du am Anfang erwarten kannst`,text:`Frühe Kraftzuwächse kommen oft von besserem Geschick und besserer Koordination zwischen Nerven und Muskeln, und körperliche Veränderungen zeigen sich stärker mit der Zeit. Ein verpasstes Training löscht deinen Fortschritt nicht aus. Mache einfach bei der nächsten geplanten Einheit weiter.`},{title:`TrainUp nutzen`,text:`Lege im Profil dein Fitnesslevel ehrlich fest, zusammen mit der Ausrüstung, die du hast, und deiner Einheitendauer. Bewerte nach jedem Training deine Anstrengung (RPE). Dein Plan ändert sich nur, wenn du ihn neu erstellst, und nie anhand von weniger als 3 Trainings. Wenn deine letzten 4 leicht (RPE 5 oder weniger) und vollständig waren, wird der nächste Plan einen Schritt härter.`}];var t=[{label:`Praktische Hinweise des ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: Gehen für die Gesundheit`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};